curl -s -X POST "$BASE/api/attest" -H "X-API-Key: $MDTOPDF_KEY" \
  -H 'Content-Type: application/json' -d '{
    "pdf": "/download/acme/contrat.pdf",
    "theme": "report@1",
    "operations": ["convert", "redact"]
  }' | jq '{attestation, sha: .claims.output_sha256, pages: .claims.pages}'

# 1. Rendre, sauvegarder côté serveur
curl -s -X POST "$BASE/api/convert" -H "X-API-Key: $MDTOPDF_KEY" \
  -H 'Content-Type: application/json' -d '{
    "markdown": "# Contrat de service\n\n## 1. Objet\n…",
    "options": {
      "theme": "report@1",
      "toc": true, "toc_depth": 2,
      "page_numbers": true,
      "page_number_format": "counter(page) \" / \" counter(pages)",
      "cover": { "title": "Contrat de service", "subtitle": "ACME × AI SmartTalk", "date": "26/07/2026" },
      "autolayout": true
    },
    "client_id": "acme", "pdf_name": "contrat"
  }'
# {"download_url":"/download/acme/contrat.pdf","layout":{"score":97,…}}

# 2. Tamponner « brouillon »
curl -s -X POST "$BASE/api/watermark" -H "X-API-Key: $MDTOPDF_KEY" \
  -H 'Content-Type: application/json' -d '{
    "pdf": "/download/acme/contrat.pdf", "text": "BROUILLON",
    "client_id": "acme", "pdf_name": "contrat-brouillon"
  }'

# 3. Sceller — toujours en dernier
curl -s -X POST "$BASE/api/protect" -H "X-API-Key: $MDTOPDF_KEY" \
  -H 'Content-Type: application/json' -d '{
    "pdf": "/download/acme/contrat-brouillon.pdf", "password": "…",
    "client_id": "acme", "pdf_name": "contrat-scelle"
  }'

